import {changeLoading} from 'stores/core/controller/securityController'
import {LIST_REAZON_CANCELLER} from 'stores/core/utils/slots'

export default defineComponent({
  name: 'BookingQuickDetailsSideModal',
  props: {
    modal: {type: Boolean, default: false},
    bookingId: {type: String, default: null}
  },
  emits: ['modal-emit', 'updated'],
  data: () => ({
    loading: false,
    participantsLoading: false,
    participantsSkeletonCount: 4,
    scheduling: null as any,
    addUserDialog: false,
    cancelDialog: false,
    loadingSearch: false,
    listUsers: [] as any[],
    userNewSelected: [] as any[],
    addUserType: 'REGISTERED',
    guestParticipant: {name: '', email: '', phone: ''},
    guestCreateEndpoint: '',
    reasonCanceler: null as any,
    reasonCanceler2: null as any,
    listReasonCanceler: LIST_REAZON_CANCELLER,
    isRefoundCancel: false
  }),
  computed: {
    ...mapState(useVenueStore, ['venue', 'addon']),
    ...mapState(useSecurityStore, ['user', 'currentPermissions']),
    courtNames(): string[] {
      const courts = this.scheduling?.courts || []
      return courts.map((court: any) => court?.courts || court).flat().map((court: any) => court?.name || court?.id || court)
    },
    totalCourts(): number {
      return this.scheduling?.courts?.map((c: any) => c.courts).flat().length || 0
    },
    maxParticipants(): number {
      const max = this.scheduling?._settings?.data?.max_num_participant || 0
      return max && this.totalCourts ? max * this.totalCourts : 4
    },
    venueLocation(): string {
      return this.venue?.address || this.venue?.location || this.venue?.name || 'Ubicación no disponible'
    },
    paymentTypeLabel(): string {
      return this.scheduling?._settings?.data?.split_payment ? 'Pago dividido' : 'Pago único'
    },
    detailsRoute(): any {
      return this.scheduling ? {name: 'b.details', params: {id: this.scheduling.id}} : undefined
    },
    bookingTypeLabel(): string {
      const type = this.scheduling?.type
      if (type === 'RECURRENT') return 'Recurrente'
      if (type === 'BLOCK') return 'Bloqueado'
      if (type === 'LESSONS') return 'Clase'
      return 'Regular'
    },
    bookingTypeEmoji(): string {
      const type = this.scheduling?.type
      if (type === 'RECURRENT') return '🗓️'
      if (type === 'LESSONS') return '🎓'
      if (type === 'BLOCK') return '🚫'
      return '📅'
    },
    participantSkeletonCount(): number {
      return Math.max(this.participantsSkeletonCount, 1)
    }
  },
  watch: {
    modal(value: boolean) {
      if (value && this.bookingId) void this.fetchBooking()
      if (!value) this.resetModalState()
    },
    bookingId(value: string) {
      if (this.modal && value) void this.fetchBooking()
    },
    addUserDialog(value: boolean) {
      if (!value) this.resetAddUserState()
    },
    cancelDialog(value: boolean) {
      if (!value) {
        this.reasonCanceler = null
        this.reasonCanceler2 = null
        this.isRefoundCancel = false
      }
    }
  },
  methods: {
    resetModalState() {
      this.scheduling = null
      this.loading = false
      this.participantsLoading = false
      this.participantsSkeletonCount = 4
      this.addUserDialog = false
      this.cancelDialog = false
      this.resetAddUserState()
      this.reasonCanceler = null
      this.reasonCanceler2 = null
      this.isRefoundCancel = false
    },
    close() {
      this.resetModalState()
      this.$emit('modal-emit', false)
    },
    async fetchBooking(options: {initial?: boolean, participantsOnly?: boolean} = {initial: true}) {
      const initial = options.initial !== false
      if (initial) {
        this.loading = true
        this.scheduling = null
      }
      if (options.participantsOnly) this.participantsLoading = true
      try {
        const response: any = await getSchedulingById_service(this.bookingId)
        this.scheduling = response.data.data
      } finally {
        if (initial) this.loading = false
        if (options.participantsOnly) this.participantsLoading = false
      }
    },
    showDate(date: number) { return moment.utc(date).format('DD MMMM YYYY') },
    showHour(date: number) { return moment.utc(date).format('hh:mm a') },
    showLongDate(date: number) { return moment.utc(date).format('dddd, DD [de] MMMM') },
    showTimeRange(date: number, range: number) {
      const start = moment.utc(date)
      return `${start.format('h:mm')} – ${start.clone().add(range, 'minutes').format('h:mma')}`
    },
    resetAddUserState() {
      this.addUserType = 'REGISTERED'
      this.userNewSelected = []
      this.listUsers = []
      this.guestParticipant = {name: '', email: '', phone: ''}
    },
    isValidGuestEmail(email: string) {
      return /\S+@\S+\.\S+/.test(email)
    },
    isAddUserDisabled() {
      const hasSlots = ((this.scheduling?._settings?.data?.max_num_participant * this.totalCourts) - this.scheduling.users.length) > 0
      if (!hasSlots) return true
      if (this.addUserType === 'REGISTERED') return !this.userNewSelected.length
      return !this.guestParticipant.name.trim() || !this.guestParticipant.phone.trim() || !this.isValidGuestEmail(this.guestParticipant.email.trim())
    },
    buildGuestParticipantPayload() {
      return {
        name: this.guestParticipant.name.trim(),
        email: this.guestParticipant.email.trim().toLowerCase(),
        phone: this.guestParticipant.phone.trim()
      }
    },
    async createGuestParticipant(guestPayload: { name: string, email: string, phone: string }) {
      if (!this.guestCreateEndpoint) {
        return {id: 'GUEST', ...guestPayload, is_guest: true, photo: 'avatar.png'}
      }
      const response = await api.post(this.guestCreateEndpoint, guestPayload)
      return response.data?.data || response.data
    },
    filterFn2(val: any, update: any) {
      this.loadingSearch = true
      if (val === '') {
        update(() => { this.listUsers = [] })
        this.loadingSearch = false
        return
      }
      update(async () => {
        const users: any = await api.post('getUsersKluboBySearch', {search: val})
        this.listUsers = users.data
        this.loadingSearch = false
      })
    },
    async addUser() {
      const hasSlots = ((this.scheduling?._settings?.data?.max_num_participant * this.totalCourts) - this.scheduling.users.length) > 0
      if (!hasSlots) return
      if (this.isAddUserDisabled()) return

      const currentCount = this.scheduling?.users?.length || 0
      const addedCount = this.addUserType === 'GUEST' ? 1 : this.userNewSelected.length
      this.participantsSkeletonCount = Math.max(currentCount + addedCount, 1)
      this.addUserDialog = false
      this.participantsLoading = true
      const isGuestFlow = this.addUserType === 'GUEST'
      let usersPayload: any[] = this.userNewSelected
      try {
        if (isGuestFlow) {
          const guestUser = await this.createGuestParticipant(this.buildGuestParticipantPayload())
          usersPayload = [guestUser]
        }
        await addUserToScheduling_service({venue: this.venue.id, scheduling: this.scheduling.id, users: usersPayload, source: 'WEB'})
        this.resetAddUserState()
        await this.fetchBooking({initial: false, participantsOnly: true})
        this.$emit('updated')
      } finally {
        this.participantsLoading = false
      }
    },
    async removeUser(userItem: any) {
      const currentCount = this.scheduling?.users?.length || 0
      this.participantsSkeletonCount = Math.max(currentCount - 1, 1)
      this.participantsLoading = true
      try {
        await removeUserToScheduling_service({venue: this.venue.id, scheduling: this.scheduling.id, users: [userItem], source: 'WEB'})
        await this.fetchBooking({initial: false, participantsOnly: true})
        this.$emit('updated')
      } finally {
        this.participantsLoading = false
      }
    },
    share() {
      const text = `Únete a la reserva:\n\nhttps://klubo.app/invite?vrid=${this.venue.id}&rid=${this.scheduling.id}`
      void copyToClipboard(text).then(() => this.$q.notify({message: 'Invitación copiada en el portapapeles', position: 'top', type: 'positive'}))
    },
    async cancelBookingBtn() {
      changeLoading(true)
      const payload = {
        venue: this.venue.id,
        booking: this.scheduling.id,
        notify: true,
        canceler: {name: this.user.name, email: this.user.email, phone: this.user.phone, photo: this.user.photo},
        reason: this.reasonCanceler?.value === 'OTHERS' ? this.reasonCanceler2 : this.reasonCanceler.label,
        refundable: this.isRefoundCancel
      }
      await cancelBooking(payload)
      this.cancelDialog = false
      this.reasonCanceler = null
      this.reasonCanceler2 = null
      await this.fetchBooking()
      this.$emit('updated')
      this.$q.notify({message: 'La reserva ha sido cancelada exitosamente', position: 'top', type: 'positive'})
      changeLoading(false)
    }
  }
})
</script>

