export const LIST_PAYMENTS_METHODS = [
  {title: "Programa de lealtad", value: "LOYALTY_PROGRAM"},
  {title: "Tarjeta de crédito", value: "CREDIT_CARD"},
  {title: "Tarjeta de débito", value: "DEBIT_CARD"},
  {title: "Transferencia bancaria", value: "BANK_TRANSFER"},
  {title: "Débito directo", value: "DIRECT_DEBIT"},
  {title: "Billetera digital", value: "DIGITAL_WALLET"},
  {title: "Botón de pago", value: "PAYMENT_BUTTON"},
  {title: "Apple Pay", value: "APPLE_PAY"},
  {title: "Google Pay", value: "GOOGLE_PAY"},
  {title: "PayPal", value: "PAYPAL"},
  {title: "Yappy", value: "YAPPY"},
  {title: "Nequi", value: "NEQUI"},
  {title: "Pago con QR", value: "QR_PAYMENT"},
  {title: "Efectivo", value: "CASH"},
  {title: "Criptomonedas", value: "CRYPTO"},
  {title: "Tarjeta prepago", value: "PREPAID_CARD"},
  {title: "Tarjeta de regalo", value: "GIFT_CARD"},
  {title: "Invitado", value: "GUEST"},
  {title: "Zelle", value: "ZELLE"},
  {title: "Stripe", value: "STRIPE"},
  {title: "Wallet", value: "WALLET"},
];

export function getPaymentTitle(data: any): any {
  const allCompleted = data.transactions?.filter((t: any) => t.status === "COMPLETED").length
  if (!Array.isArray(data.transactions) || data.transactions.length === 0) {
    return {
      class: 'bg-[#F3164E] text-white',
      icon: 'mdi-close',
      message: "Sin pago",
    };
  }

  if (data.split_payment) {
    if (allCompleted !== data.users_ids_count) {
      return {
        class: 'bg-[#84E4AE] text-black',
        icon: 'mdi-account-off',
        message: `Pago fraccionado ${allCompleted}/${data.users_ids_count}`,
      };
    }
  }


  if (allCompleted === data.users_ids_count) {
    return {
      class: 'bg-[#1E874C] text-white',
      icon: 'mdi-check',
      message: `Pago total`,
    };
  }

  if (allCompleted === 0) {
    return {
      class: 'bg-[#FFC233] text-[#0C0636]',
      icon: 'mdi-alert-circle-outline',
      message: `Pago pendiente`,
    };
  }

  return data.transactions
}

