getBookingPaymentStatus() {
  if (this.scheduling?.type === 'BLOCK' || this.scheduling?.status === 'BLOCKED') return 'blocked'

  const users = this.scheduling?.users || []
  const transactions = this.scheduling?.transactions || users.map((user: any) => user.transaction).filter(Boolean)
  const completedPayments = transactions.filter((transaction: any) => transaction?.status === 'COMPLETED').length
