getParticipantPaymentStatus(user: any) {
  const status = user?.transaction?.status
  if (status === 'COMPLETED') return 'completed'
  if (status === 'REFUND') return 'refund'
  return 'pending'
},
getParticipantPaymentStatusIcon(user: any) {
  const status = this.getParticipantPaymentStatus(user)
  if (status === 'completed') return 'mdi-check-circle'
  if (status === 'refund') return 'mdi-cash-refund'
  return 'mdi-clock-time-four-outline'
},
getParticipantPaymentStatusClass(user: any) {
  return `payment-status-icon--${this.getParticipantPaymentStatus(user)}`
},
getParticipantPaymentStatusLabel(user: any) {
  const status = this.getParticipantPaymentStatus(user)
  if (status === 'completed') return 'Completado'
  if (status === 'refund') return 'Reembolsado'
  return 'Pendiente'
},
